  ].join('\n');
}

function formatParserError(programName, message) {
  return `${formatUsage(programName)}${programName}: error: ${message}\n`;
}

function getProgramName(argv) {
  return basename(argv[1] ?? 'test4.mjs');
}

function isRecognizedOption(flag) {
  return OPTION_ORDER.includes(flag);
}

function getOptionValue(tokens, index, flag, programName) {
  const token = tokens[index];
  const equalsIndex = token.indexOf('=');

  if (equalsIndex !== -1) {
    return {
      nextIndex: index,
      value: token.slice(equalsIndex + 1),
