export function parseTest4Arguments(argv = process.argv) {
  const programName = getProgramName(argv);
  const tokens = argv.slice(2);
  const parsed = {
    a: undefined,
    b: undefined,
    c: undefined,
  };
  const extras = [];

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (token === '--') {
      extras.push(...tokens.slice(index + 1));
      break;
    }

    if (token === '-h' || token === '--help') {
      throw new ArgumentParseExit(0, 'stdout', formatHelp(programName));
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      const flag = equalsIndex === -1 ? token : token.slice(0, equalsIndex);

      if (isRecognizedOption(flag)) {
        const { nextIndex, value } = getOptionValue(
          tokens,
          index,
          flag,
          programName,
        );

        index = nextIndex;

        if (flag === '--a') {
          parsed.a = value;
          continue;
