              2,
              'stderr',
              formatParserError(
                programName,
                `argument --b: invalid int value: ${pythonRepr(value)}`,
              ),
            );
          }

          throw error;
        }

        continue;
      }
    }

    extras.push(token);
  }

  const missing = OPTION_ORDER.filter((flag) => parsed[flag.slice(2)] === undefined);

